    pprev, uprev = d["power_output_t0"], d["unit_on_t0"]
else:
    pprev, uprev = P[g][t - 2], U[g][t - 2]
if P[g][tt] - pprev > d["ramp_up_limit"] * uprev + d["ramp_startup_limit"] * Y[g][tt] + TOL:
    errors.append(f"{g} t{t} ramp up violated")
if pprev - P[g][tt] > d["ramp_down_limit"] * U[g][tt] + d["ramp_shutdown_limit"] * Z[g][tt] + TOL:
    errors.append(f"{g} t{t} ramp down violated")

