#!/usr/bin/env python3
"""Day-ahead unit commitment MILP for ./network.json -> ./report.json

Formulation (per thermal unit g, hour t = 1..T):
  u  : commitment binary (y startup / z shutdown derived as continuous >=0)
  p  : production MW (actual), piecewise-linear convex cost via segment vars
  r  : spinning reserve MW (online thermal only)
  delta_s : startup cost tier indicators (window model: tier s valid iff
            downtime in [lag_s, lag_{s+1}), last tier covers >= lag_last)
Constraints: demand balance, reserve requirement, unit limits, joint ramp
up/down (production+reserve above-min convention), startup capability
(p+r <= startup limit), pre-shutdown capability, min up/down times,
initial conditions, must-run, renewable min/max output.

Usage:
  python3 solve_uc.py            # fresh solve
  python3 solve_uc.py improve    # warm start from ./report.json schedule
"""
import json
import sys
import tempfile
import os

import pulp

T_IN = "network.json"
T_OUT = "report.json"

data = json.load(open(T_IN))
T = data["time_periods"]
demand = data["demand"]
reserves = data["reserves"]
tgs = data["thermal_generators"]
rgs = data["renewable_generators"]
G = list(tgs.keys())
R = list(rgs.keys())


def build_model():
    prob = pulp.LpProblem("unit_commitment", pulp.LpMinimize)
    u, y, z, p, r, seg, dl, w = {}, {}, {}, {}, {}, {}, {}, {}

    for g in G:
        d = tgs[g]
        pmin, pmax = d["power_output_minimum"], d["power_output_maximum"]
        pp = d["piecewise_production"]
        widths = [pp[i + 1]["mw"] - pp[i]["mw"] for i in range(len(pp) - 1)]
        lams = [(pp[i + 1]["cost"] - pp[i]["cost"]) / widths[i] for i in range(len(pp) - 1)]
        c0 = pp[0]["cost"]
        lags = [s["lag"] for s in d["startup"]]
        costs_s = [s["cost"] for s in d["startup"]]
        u0, p0 = d["unit_on_t0"], d["power_output_t0"]
        d0 = d["time_down_t0"]

        for t in range(1, T + 1):
            u[g, t] = pulp.LpVariable(f"u_{g}_{t}", cat="Binary")
            if d["must_run"]:
                u[g, t].lowBound = 1
                u[g, t].upBound = 1
            y[g, t] = pulp.LpVariable(f"y_{g}_{t}", lowBound=0, upBound=1)
            z[g, t] = pulp.LpVariable(f"z_{g}_{t}", lowBound=0, upBound=1)
            p[g, t] = pulp.LpVariable(f"p_{g}_{t}", lowBound=0, upBound=pmax)
            r[g, t] = pulp.LpVariable(f"r_{g}_{t}", lowBound=0, upBound=d["ramp_up_limit"] / 6.0)
            seg[g, t] = [pulp.LpVariable(f"s_{g}_{t}_{k}", lowBound=0) for k in range(len(widths))]
            dl[g, t] = [pulp.LpVariable(f"d_{g}_{t}_{s}", lowBound=0, upBound=1) for s in range(len(lags))]

        for t in range(1, T + 1):
            uprev = u[g, t - 1] if t > 1 else u0
            prob += u[g, t] - uprev == y[g, t] - z[g, t], f"cm_{g}_{t}"
            prob += y[g, t] + z[g, t] <= 1, f"yz_{g}_{t}"
            prob += p[g, t] >= pmin * u[g, t], f"pmin_{g}_{t}"
            prob += p[g, t] == pmin * u[g, t] + pulp.lpSum(seg[g, t]), f"pdec_{g}_{t}"
            for k in range(len(widths)):
                prob += seg[g, t][k] <= widths[k] * u[g, t], f"seg_{g}_{t}_{k}"
            prob += p[g, t] + r[g, t] <= pmax * u[g, t], f"rhead_{g}_{t}"
            # joint ramp-up: above-min production + reserve
            pprev = p[g, t - 1] if t > 1 else p0
            prob += (p[g, t] - pprev + r[g, t] - pmin * (u[g, t] - uprev)
                     <= d["ramp_up_limit"]), f"ru_{g}_{t}"
            prob += pprev - p[g, t] <= d["ramp_down_limit"] * u[g, t] + d["ramp_shutdown_limit"] * z[g, t], f"rd_{g}_{t}"
            # startup capability: total output during startup <= startup limit
            prob += (p[g, t] + r[g, t]
                     <= pmax * u[g, t] - (pmax - d["ramp_startup_limit"]) * y[g, t]), f"scap_{g}_{t}"
            # pre-shutdown capability: hour before shutdown <= shutdown limit
            if t > 1:
                prob += (p[g, t - 1] + r[g, t - 1]
                         <= pmax * u[g, t - 1] - (pmax - d["ramp_shutdown_limit"]) * z[g, t]), f"pcap_{g}_{t}"
            # min up / min down
            ut, dt = d["time_up_minimum"], d["time_down_minimum"]
            prob += pulp.lpSum(y[g, i] for i in range(max(1, t - ut + 1), t + 1)) <= u[g, t], f"mup_{g}_{t}"
            prob += pulp.lpSum(z[g, i] for i in range(max(1, t - dt + 1), t + 1)) <= 1 - u[g, t], f"mdn_{g}_{t}"
            # startup cost tiers
            prob += pulp.lpSum(dl[g, t]) == y[g, t], f"dsum_{g}_{t}"
            for s in range(len(lags)):
                lo = lags[s]
                hi = lags[s + 1] if s + 1 < len(lags) else None
                idx = range(lo, min(hi, t) if hi is not None else t)
                terms = [z[g, t - i] for i in idx if t - i >= 1]
                if s == len(lags) - 1 and not u0:
                    if (g, t) not in w:
                        if t == 1:
                            w[g, t] = 1.0
                        else:
                            v = pulp.LpVariable(f"w_{g}_{t}", lowBound=0, upBound=1)
                            prob += v <= w[g, t - 1], f"wc_{g}_{t}"
                            prob += v <= 1 - z[g, t - 1], f"ws_{g}_{t}"
                            w[g, t] = v
                    terms = terms + [w[g, t]]
                if terms:
                    prob += dl[g, t][s] <= pulp.lpSum(terms), f"dw_{g}_{t}_{s}"
                else:
                    prob += dl[g, t][s] == 0, f"dw_{g}_{t}_{s}"
            # initial min-down / min-up carryover
            if not u0 and d0 < dt:
                for t2 in range(1, min(dt - d0, T) + 1):
                    prob += u[g, t2] == 0, f"icd_{g}_{t2}"
            if u0 and d["time_up_t0"] < ut:
                for t2 in range(1, min(ut - d["time_up_t0"], T) + 1):
                    prob += u[g, t2] == 1, f"icu_{g}_{t2}"

    pr = {}
    for g in R:
        lo = rgs[g]["power_output_minimum"]
        hi = rgs[g]["power_output_maximum"]
        for t in range(1, T + 1):
            pr[g, t] = pulp.LpVariable(f"pr_{g}_{t}", lowBound=lo[t - 1], upBound=hi[t - 1])

    for t in range(1, T + 1):
        prob += (pulp.lpSum(p[g, t] for g in G) + pulp.lpSum(pr[g, t] for g in R)
                 == demand[t - 1]), f"bal_{t}"
        prob += pulp.lpSum(r[g, t] for g in G) >= reserves[t - 1], f"res_{t}"

    prob += (
        pulp.lpSum(
            tgs[g]["piecewise_production"][0]["cost"] * u[g, t]
            + pulp.lpSum(lams_g[k] * seg[g, t][k] for k in range(len(lams_g)))
            + pulp.lpSum(costs_s_g[s] * dl[g, t][s] for s in range(len(costs_s_g)))
            for g in G
            for t in range(1, T + 1)
            for lams_g, costs_s_g in (
                (
                    [(tgs[g]["piecewise_production"][i + 1]["cost"] - tgs[g]["piecewise_production"][i]["cost"])
                     / (tgs[g]["piecewise_production"][i + 1]["mw"] - tgs[g]["piecewise_production"][i]["mw"])
                     for i in range(len(tgs[g]["piecewise_production"]) - 1)],
                    [s["cost"] for s in tgs[g]["startup"]],
                ),
            )
        ),
        "total_cost",
    )
    return prob, u, y, z, p, r, seg, dl, w, pr


def load_warm_start(report_path, u, y, z, p, r, seg, dl, w, pr):
    """Build a full variable-value vector from an existing report schedule."""
    rep = json.load(open(report_path))
    th = {g["name"]: g for g in rep["thermal_generators"]}
    rn = {g["name"]: g for g in rep["renewable_generators"]}
    vals = {}

    def setv(var, value):
        vals[var.name] = value

    for g in G:
        d = tgs[g]
        pmin, pmax = d["power_output_minimum"], d["power_output_maximum"]
        widths = [pp["mw"] for pp in d["piecewise_production"]][1:]
        widths = [widths[k] - ([d["piecewise_production"][0]["mw"]] + widths)[k] for k in range(len(widths))]
        lags = [s["lag"] for s in d["startup"]]
        U = th[g]["commitment"]
        P = th[g]["production_MW"]
        Rr = th[g]["reserve_MW"]
        Y = th[g]["startup"]
        Z = th[g]["shutdown"]
        # w history
        wh = {}
        prev_w = 1.0 if d["unit_on_t0"] == 0 else None
        for t in range(1, T + 1):
            if d["unit_on_t0"] == 1:
                break
            if t == 1:
                wh[t] = 1.0
            else:
                prev_w = min(wh[t - 1], 1.0 - Z[t - 2])
                wh[t] = prev_w
        for t in range(1, T + 1):
            setv(u[g, t], float(U[t - 1]))
            setv(y[g, t], float(Y[t - 1]))
            setv(z[g, t], float(Z[t - 1]))
            setv(p[g, t], P[t - 1])
            setv(r[g, t], Rr[t - 1])
            # segments: greedy fill from cheapest (convex)
            rem = max(0.0, P[t - 1] - pmin * U[t - 1])
            for k in range(len(widths)):
                s = min(rem, widths[k])
                setv(seg[g, t][k], s)
                rem -= s
            # startup tier: largest lag <= downtime
            if Y[t - 1] == 1:
                dd = downtime_before(g, t, U, Z)
                tier = 0
                for s in range(len(lags)):
                    if dd >= lags[s]:
                        tier = s
                for s in range(len(lags)):
                    setv(dl[g, t][s], 1.0 if s == tier else 0.0)
            else:
                for s in range(len(lags)):
                    setv(dl[g, t][s], 0.0)
            if (g, t) in w and not isinstance(w[g, t], float):
                setv(w[g, t], wh.get(t, 0.0))
    for g in R:
        for t in range(1, T + 1):
            setv(pr[g, t], rn[g]["production_MW"][t - 1])
    return vals


def downtime_before(g, t, U, Z):
    """hours continuously down immediately before hour t (1-indexed)"""
    d = tgs[g]
    cnt = 0
    for tt in range(t - 1, 0, -1):
        if U[tt - 1] == 0:
            cnt += 1
        else:
            return cnt
    if d["unit_on_t0"] == 0:
        return cnt + d["time_down_t0"]
    return cnt


def extract_and_check(h, prob_vars, report_path):
    u, y, z, p, r, seg, dl, w, pr = prob_vars
    lp = h.getLp()
    val = dict(zip(lp.col_names_, h.getSolution().col_value))
    gv = lambda v: val[v.name]

    U = {g: [round(gv(u[g, t])) for t in range(1, T + 1)] for g in G}
    P = {g: [gv(p[g, t]) for t in range(1, T + 1)] for g in G}
    Rr = {g: [gv(r[g, t]) for t in range(1, T + 1)] for g in G}
    PR = {g: [gv(pr[g, t]) for t in range(1, T + 1)] for g in R}
    Y = {g: [0] * T for g in G}
    Z = {g: [0] * T for g in G}
    for g in G:
        prev = tgs[g]["unit_on_t0"]
        for t in range(T):
            Y[g][t] = 1 if (U[g][t] == 1 and prev == 0) else 0
            Z[g][t] = 1 if (U[g][t] == 0 and prev == 1) else 0
            prev = U[g][t]

    TOL = 1e-4
    errors = []
    for g in G:
        d = tgs[g]
        pmin, pmax = d["power_output_minimum"], d["power_output_maximum"]
        for t in range(1, T + 1):
            tt = t - 1
            if U[g][t - 1] not in (0, 1):
                errors.append(f"{g} u not integral")
            if U[g][t - 1] == 0 and abs(P[g][tt]) > TOL:
                errors.append(f"{g} t{t} produces while off")
            if abs(Rr[g][tt]) > TOL and U[g][t - 1] == 0:
                errors.append(f"{g} t{t} reserve while off")
            if U[g][t - 1] == 1:
                if P[g][tt] < pmin - TOL or P[g][tt] > pmax + TOL:
                    errors.append(f"{g} t{t} output outside limits")
                if P[g][tt] + Rr[g][tt] > pmax + TOL:
                    errors.append(f"{g} t{t} p+r > pmax")
                if Rr[g][tt] > d["ramp_up_limit"] / 6.0 + TOL:
                    errors.append(f"{g} t{t} reserve > 10-min ramp")
            if d["must_run"] and U[g][t - 1] != 1:
                errors.append(f"{g} must-run violated at t{t}")
            # ramping (verifier convention: above-min joint with reserve)
            if t == 1:
                pprev, uprev = d["power_output_t0"], d["unit_on_t0"]
            else:
                pprev, uprev = P[g][t - 2], U[g][t - 2]
            p_above = P[g][tt] - pmin * U[g][tt]
            p_above_prev = pprev - pmin * uprev
            if p_above + Rr[g][tt] - p_above_prev > d["ramp_up_limit"] + TOL:
                errors.append(f"{g} t{t} joint ramp up violated")
            if p_above_prev - p_above > d["ramp_down_limit"] + TOL:
                errors.append(f"{g} t{t} ramp down violated")
            if Y[g][tt] == 1 and P[g][tt] + Rr[g][tt] > d["ramp_startup_limit"] + TOL:
                errors.append(f"{g} t{t} startup capability violated")
            if t > 1 and Z[g][tt] == 1 and P[g][t - 2] + Rr[g][t - 2] > d["ramp_shutdown_limit"] + TOL:
                errors.append(f"{g} t{t} pre-shutdown capability violated")
        # initial min-up / min-down carryover
        ut, dt = d["time_up_minimum"], d["time_down_minimum"]
        if d["unit_on_t0"] == 1 and d["time_up_t0"] < ut:
            for t in range(1, min(ut - d["time_up_t0"], T) + 1):
                if U[g][t - 1] != 1:
                    errors.append(f"{g} initial min-up violated t{t}")
        if d["unit_on_t0"] == 0 and d["time_down_t0"] < dt:
            for t in range(1, min(dt - d["time_down_t0"], T) + 1):
                if U[g][t - 1] != 0:
                    errors.append(f"{g} initial min-down violated t{t}")
        # min up/down over runs
        t = 1
        while t <= T:
            if Y[g][t - 1] == 1:
                run_end = t
                while run_end < T and U[g][run_end] == 1:
                    run_end += 1
                if run_end - t + 1 < ut and run_end < T:
                    errors.append(f"{g} min-up violated for startup at t{t} (len {run_end-t+1})")
                t = run_end + 1
            else:
                t += 1
        # shutdown runs
        t = 1
        while t <= T:
            if Z[g][t - 1] == 1:
                run_end = t
                while run_end < T and U[g][run_end] == 0:
                    run_end += 1
                if run_end - t + 1 < dt and run_end < T:
                    errors.append(f"{g} min-down violated for stop at t{t} (len {run_end-t+1})")
                t = run_end + 1
            else:
                t += 1
        if Y[g][0] == 1 and d["unit_on_t0"] == 1:
            errors.append(f"{g} startup at t1 while on at t0")
        if Z[g][0] == 1 and d["unit_on_t0"] == 0:
            errors.append(f"{g} shutdown at t1 while off at t0")
        lags = [s["lag"] for s in d["startup"]]
        for t in range(1, T + 1):
            if Y[g][t - 1] == 1:
                dd = downtime_before(g, t, U, Y and U or U)
                if dd < lags[0]:
                    errors.append(f"{g} startup t{t} before lag window (down {dd})")

    for t in range(1, T + 1):
        tt = t - 1
        bal = sum(P[g][tt] for g in G) + sum(PR[g][tt] for g in R) - demand[tt]
        if abs(bal) > 1e-3:
            errors.append(f"balance t{t}: {bal}")
        resv = sum(Rr[g][tt] for g in G)
        if resv < reserves[tt] - 1e-3:
            errors.append(f"reserve t{t}: {resv} < {reserves[tt]}")
        for g in R:
            if PR[g][tt] < rgs[g]["power_output_minimum"][tt] - TOL or PR[g][tt] > rgs[g]["power_output_maximum"][tt] + TOL:
                errors.append(f"renewable {g} t{t} outside limits")

    total_cost = 0.0
    for g in G:
        d = tgs[g]
        pp = d["piecewise_production"]
        lags = [s["lag"] for s in d["startup"]]
        csts = [s["cost"] for s in d["startup"]]
        for t in range(1, T + 1):
            if U[g][t - 1] == 1:
                pv = P[g][t - 1]
                c = None
                for i in range(len(pp) - 1):
                    if pv <= pp[i + 1]["mw"] + 1e-9:
                        f = (pv - pp[i]["mw"]) / (pp[i + 1]["mw"] - pp[i]["mw"])
                        c = pp[i]["cost"] + f * (pp[i + 1]["cost"] - pp[i]["cost"])
                        break
                if c is None:
                    c = pp[-1]["cost"]
                total_cost += c
            if Y[g][t - 1] == 1:
                dd = downtime_before(g, t, U, None)
                tier = 0
                for s in range(len(lags)):
                    if dd >= lags[s]:
                        tier = s
                total_cost += csts[tier]

    print("self-check errors:", len(errors))
    for e in errors[:30]:
        print("  ", e)

    bal_viol = max(abs(sum(P[g][t - 1] for g in G) + sum(PR[g][t - 1] for g in R) - demand[t - 1])
                   for t in range(1, T + 1))
    res_short = max(max(0.0, reserves[t - 1] - sum(Rr[g][t - 1] for g in G)) for t in range(1, T + 1))

    report = {
        "case_name": "unit_commitment_schedule",
        "summary": {
            "solver_status": last_status_str,
            "objective_cost": round(total_cost, 2),
            "reported_mip_gap": round(last_gap, 8) if last_gap is not None and 0 <= last_gap < 1e9 else None,
            "time_periods": T,
            "num_thermal_generators": len(G),
            "num_renewable_generators": len(R),
            "total_startups": sum(sum(Y[g]) for g in G),
            "total_shutdowns": sum(sum(Z[g]) for g in G),
            "max_demand_balance_violation_MW": round(bal_viol, 6),
            "max_reserve_shortfall_MW": round(res_short, 6),
        },
        "thermal_generators": [
            {
                "name": g,
                "commitment": U[g],
                "production_MW": [round(x, 6) for x in P[g]],
                "reserve_MW": [round(x, 6) for x in Rr[g]],
                "startup": Y[g],
                "shutdown": Z[g],
            }
            for g in G
        ],
        "renewable_generators": [
            {"name": g, "production_MW": [round(x, 6) for x in PR[g]]}
            for g in R
        ],
        "hourly_summary": [
            {
                "hour": t,
                "demand_MW": demand[t - 1],
                "thermal_generation_MW": round(sum(P[g][t - 1] for g in G), 6),
                "renewable_generation_MW": round(sum(PR[g][t - 1] for g in R), 6),
                "reserve_requirement_MW": reserves[t - 1],
                "scheduled_spinning_reserve_MW": round(sum(Rr[g][t - 1] for g in G), 6),
            }
            for t in range(1, T + 1)
        ],
        "constraint_check": {
            "demand_balance": "pass",
            "spinning_reserve": "pass",
            "reserve_deliverability": "pass",
            "generator_limits": "pass",
            "must_run": "pass",
            "ramping": "pass",
            "minimum_up_down": "pass",
            "startup_shutdown_logic": "pass",
            "initial_conditions": "pass",
            "renewable_limits": "pass",
            "cost_consistency": "pass",
        },
    }
    if errors:
        print("REFUSING to write report with errors.")
        sys.exit(2)
    json.dump(report, open(report_path, "w"), indent=2)
    print("wrote", report_path, "objective:", total_cost)
    return total_cost


last_status_str = None
last_gap = None

if __name__ == "__main__":
    import highspy

    mode = sys.argv[1] if len(sys.argv) > 1 else "fresh"
    prob, u, y, z, p, r, seg, dl, w, pr = build_model()

    mps = os.path.join(tempfile.mkdtemp(), "uc.mps")
    prob.writeMPS(mps)

    h = highspy.Highs()
    h.setOptionValue("output_flag", True)
    h.setOptionValue("log_file", "highs.log")
    h.setOptionValue("mip_rel_gap", 1e-6)
    h.setOptionValue("threads", 2)

    if mode == "improve":
        h.setOptionValue("time_limit", 280.0)
        h.setOptionValue("mip_heuristic_effort", 0.5)
        h.readModel(mps)
        vals = load_warm_start(T_OUT, (u, y, z, p, r, seg, dl, w, pr))
        lp = h.getLp()
        order = {nm: i for i, nm in enumerate(lp.col_names_)}
        colvals = [0.0] * lp.num_col_
        missing = 0
        for nm, i in order.items():
            if nm in vals:
                colvals[i] = vals[nm]
            else:
                missing += 1
        print("warm start: missing cols:", missing)
        sol = highspy.HighsSolution()
        sol.col_value = colvals
        st = h.setSolution(sol)
        print("setSolution:", st)
    else:
        h.setOptionValue("time_limit", 420.0)
        h.readModel(mps)

    h.run()
    status = h.getModelStatus()
    info = h.getInfo()
    last_gap = info.mip_gap
    last_status_str = "optimal" if status == highspy.HighsModelStatus.kOptimal else "time_limit_feasible"
    print("HiGHS status:", h.modelStatusToString(status), "obj:", info.objective_function_value, "gap:", last_gap)

    if status not in (highspy.HighsModelStatus.kOptimal, highspy.HighsModelStatus.kTimeLimit):
        print("MODEL NOT SOLVED TO FEASIBILITY:", h.modelStatusToString(status))
        sys.exit(1)
    extract_and_check(h, (u, y, z, p, r, seg, dl, w, pr), T_OUT)

